use mip_codex::{heuristic::Repair,mps,solve::Result};
use std::{cmp::Ordering,collections::BinaryHeap,time::{Instant,Duration}};
#[derive(Clone,Copy)]struct Entry{score:f64,j:usize,gain:usize}
impl PartialEq for Entry{fn eq(&self,o:&Self)->bool{self.score.to_bits()==o.score.to_bits()&&self.j==o.j&&self.gain==o.gain}}impl Eq for Entry{}
impl Ord for Entry{fn cmp(&self,o:&Self)->Ordering{o.score.total_cmp(&self.score).then_with(||o.j.cmp(&self.j)).then_with(||self.gain.cmp(&o.gain))}}impl PartialOrd for Entry{fn partial_cmp(&self,o:&Self)->Option<Ordering>{Some(self.cmp(o))}}
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mps::read(&a[1]).unwrap();let started=Instant::now();let end=started+Duration::from_secs_f64(a[2].parse().unwrap());let n=m.variables.len();let supported=!m.maximize&&n<=1_000_000&&m.variables.iter().all(|v|v.integer&&v.lower==Some(0.)&&v.upper==Some(1.)&&v.objective.is_finite()&&v.objective>=0.)&&m.rows.iter().all(|r|r.lower.is_some_and(|l|l>0.&&l<=1.)&&r.upper.is_none()&&r.coefficients.iter().all(|&(_,c)|c==1.));if !supported{println!("{}",serde_json::json!({"supported":false}));return;}let mut incidence=vec![vec![];n];let mut work=0usize;for(i,r)in m.rows.iter().enumerate(){for&(j,_)in&r.coefficients{incidence[j].push(i);work+=1;}}
let mut gain:Vec<_>=incidence.iter().map(Vec::len).collect();let mut heap=BinaryHeap::new();for j in 0..n{if gain[j]>0{heap.push(Entry{score:m.variables[j].objective/gain[j]as f64,j,gain:gain[j]});}}let mut selected=vec![false;n];let mut counts=vec![0usize;m.rows.len()];let mut remaining=m.rows.len();let mut additions=0;
while remaining>0&&Instant::now()<end&&work<100_000_000{let Some(e)=heap.pop()else{break;};if gain[e.j]==0||selected[e.j]{continue;}if e.gain!=gain[e.j]{heap.push(Entry{score:m.variables[e.j].objective/gain[e.j]as f64,j:e.j,gain:gain[e.j]});continue;}selected[e.j]=true;additions+=1;for&i in&incidence[e.j]{if counts[i]==0{remaining-=1;for&(j,_)in&m.rows[i].coefficients{gain[j]=gain[j].saturating_sub(1);work+=1;}}counts[i]+=1;}}
let mut removals=0;if remaining==0{let mut chosen:Vec<_>=(0..n).filter(|&j|selected[j]).collect();chosen.sort_by(|&j,&k|m.variables[k].objective.total_cmp(&m.variables[j].objective).then_with(||k.cmp(&j)));for j in chosen{if Instant::now()>=end{break;}if incidence[j].iter().all(|&i|counts[i]>1){selected[j]=false;removals+=1;for&i in&incidence[j]{counts[i]-=1;}}}}
let x:Vec<_>=selected.iter().map(|&s|if s{1.}else{0.}).collect();let valid=remaining==0&&Repair::new(&m).candidate_check(&x);let r=Result{status:if valid{"feasible_cover_diagnostic"}else{"unknown"}.into(),objective:valid.then(||m.objective(&x)),values:valid.then(||m.variables.iter().zip(x).map(|(v,x)|(v.name.clone(),x)).collect()),seconds:started.elapsed().as_secs_f64(),..Result::default()};serde_json::to_writer(std::fs::File::create(&a[3]).unwrap(),&r).unwrap();println!("{}",serde_json::json!({"supported":true,"objective":r.objective,"valid":valid,"work":work,"additions":additions,"removals":removals,"remaining":remaining,"seconds":r.seconds}));}
